record Numbers { values: Number[] }
record Total { sum: Number count: Number }

fn total(numbers: Numbers) -> Total {
  var sum = 0
  var count = 0
  for value in numbers.values {
    sum = sum + value
    count = count + 1
  }
  return {sum: sum, count: count}
}

workflow main(numbers: Numbers) -> Total {
  step compute {
    let result: Total = total(numbers: numbers)
    return result
  }
}

record Request { n: Number }
record Result { value: Number }

fn compute_factorial(n: Number) -> Number recurse 16 {
  return if n <= 1 { 1 } else { n * compute_factorial(n: n - 1) }
}

fn calculate(request: Request) -> Result {
  let val: Number = compute_factorial(n: request.n)
  return {value: val}
}

workflow main(request: Request) -> Result {
  step compute {
    let res: Result = calculate(request: request)
    return res
  }
}

record Numbers {
  values: Number[]
}

fn double_numbers(numbers: Numbers) -> Numbers {
  let doubled: Number[] = for value in numbers.values { value * 2 }
  return {values: doubled}
}

workflow main(numbers: Numbers) -> Numbers {
  step compute {
    let result: Numbers = double_numbers(numbers: numbers)
    return result
  }
}

record Command { name: Text }
record Reply { text: Text }

fn evaluate_command(command: Command) -> Reply {
  let reply_text: Text = match command.name {
    case "start" { "Starting" }
    case "stop" { "Stopping" }
    case _ { "Unknown command" }
  }
  return {text: reply_text}
}

workflow main(command: Command) -> Reply {
  step run {
    let reply: Reply = evaluate_command(command: command)
    return reply
  }
}

record Access { age: Number member: Bool banned: Bool }
record Decision { allowed: Bool }

fn evaluate_access(access: Access) -> Decision {
  let allowed: Bool = if access.banned { false } else {
    if access.age >= 18 { true } else { access.member }
  }
  return {allowed: allowed}
}

workflow main(access: Access) -> Decision {
  step check {
    let decision: Decision = evaluate_access(access: access)
    return decision
  }
}

record Reading { celsius: Number }
record Temperature { fahrenheit: Number }
record Report { fahrenheit: Number, hot: Bool }

fn calc_fahrenheit(reading: Reading) -> Temperature {
  let f: Number = reading.celsius * 9 / 5 + 32
  return {fahrenheit: f}
}

fn build_report(temperature: Temperature) -> Report {
  let is_hot: Bool = temperature.fahrenheit > 86
  return {fahrenheit: temperature.fahrenheit, hot: is_hot}
}

workflow convert(reading: Reading) -> Temperature {
  step convert_step {
    let temperature: Temperature = calc_fahrenheit(reading: reading)
    return temperature
  }
}

workflow main(reading: Reading) -> Report {
  step temp_step {
    let temperature: Temperature = call convert(reading: reading)
    return temperature
  }
  step report_step {
    let report: Report = build_report(temperature: temperature)
    return report
  }
}

record Question { text: Text }
record Answer { text: Text }

model assistant {
  input: Question
  output: Answer
}

workflow main(question: Question) -> Answer {
  step respond {
    let answer: Answer = use_model assistant(text: question.text)
    return answer
  }
}

record Ticket { text: Text }
record Label { category: Text, confidence: Number }
record Routing { queue: Text, escalate: Bool }

model classifier {
  input: Ticket
  output: Label
}

fn route_ticket(label: Label) -> Routing {
  let escalate: Bool = label.confidence < 0.6
  return {queue: label.category, escalate: escalate}
}

workflow main(ticket: Ticket) -> Routing {
  step classify {
    let label: Label = use_model classifier(text: ticket.text)
    return label
  }
  step route {
    let routing: Routing = route_ticket(label: label)
    return routing
  }
}

record Topic { title: Text }
record Draft { text: Text }
record Final { text: Text, approved: Bool }

model drafter {
  input: Topic
  output: Draft
}

model editor {
  input: Draft
  output: Final
}

workflow main(topic: Topic) -> Final {
  step make_draft {
    let draft: Draft = use_model drafter(title: topic.title)
    return draft
  }
  step make_final {
    let final: Final = use_model editor(text: draft.text)
    return final
  }
}

record Document {
  body: Text
}

record Summary {
  text: Text
}

model summarizer {
  input: Document
  output: Summary
  deployment: "local-summarizer"
  parameters: {
    temperature: 0.2
    max_output_tokens: 200
  }
}

workflow main(document: Document) -> Summary {
  step summarize {
    let summary: Summary = use_model summarizer(body: document.body)
    return summary
  }
}

record City { name: Text }
record Weather { celsius: Number, conditions: Text }

tool get_weather {
  source mcp "weather"
  operation: "current"
  access: observe
  input: City
  output: Weather
}

agent forecaster {
  can: [get_weather]
}

workflow main(city: City) -> Weather {
  step look_up {
    let weather: Weather = execute forecaster.get_weather(name: city.name)
    return weather
  }
}

record Sku { code: Text }
record Stock { quantity: Number }
record Availability { in_stock: Bool, quantity: Number }

tool lookup_stock {
  source mcp "inventory"
  operation: "lookup"
  access: observe
  input: Sku
  output: Stock
}

agent clerk {
  instructions: "Look up stock."
  can: [lookup_stock]
}

fn make_availability(stock: Stock) -> Availability {
  let in_stock: Bool = if stock.quantity > 0 { true } else { false }
  return {in_stock: in_stock, quantity: stock.quantity}
}

workflow main(sku: Sku) -> Availability {
  step fetch_stock {
    let stock: Stock = execute clerk.lookup_stock(code: sku.code)
    return stock
  }
  step check_stock {
    let availability: Availability = make_availability(stock: stock)
    return availability
  }
}

record Log {
  lines: Text[]
}

tool read_log {
  source mcp "logs"
  operation: "read"
  access: observe
  output: Log
}

agent auditor {
  instructions: "Read the log."
  can: [read_log]
  cannot: [delete_log, shell]
}

workflow main() -> Log {
  step read {
    let log: Log = execute auditor.read_log()
    return log
  }
}

record Email {
  to: Text
  subject: Text
}

record Receipt {
  sent: Bool
}

tool send_email {
  source mcp "mail"
  operation: "send"
  access: execute
  input: Email
  output: Receipt
}

agent messenger {
  instructions: "Send the email."
  can: [send_email]
}

workflow main(email: Email) -> Receipt {
  step send {
    let receipt: Receipt = execute messenger.send_email(to: email.to, subject: email.subject)
    return receipt
  }
  require approval
}

record Question { text: Text }
record SearchRequest { query: Text }
record SearchHit { source: Text, excerpt: Text }
record SearchResults { hits: SearchHit[] }
record Answer { text: Text, sources: Text[] }

model reader {
  input: Question
  output: Answer
}

tool search_docs {
  source mcp "documents"
  operation: "search"
  access: observe
  input: SearchRequest
  output: SearchResults
}

agent researcher {
  model: reader
  instructions: "Answer the question using document search."
  can: [search_docs]
  cannot: [write_files]
  max_steps: 4
}

workflow main(question: Question) -> Answer {
  step run_research {
    let answer: Answer = ask researcher(text: question.text)
    return answer
  }
}

record Brief { text: Text }

model writer_model {
  input: Brief
  output: Brief
}

agent writer {
  model: writer_model
  instructions: "Improve the brief."
  can: []
  cannot: [shell, delete_files]
  max_steps: 4
}

workflow refine(brief: Brief) -> Brief {
  step improve {
    let improved: Brief = ask writer(text: brief.text)
    return improved
  }
}

swarm Panel {
  agents: [writer]
  workflow: refine
  max_rounds: 2
  require approval
}
